/**
 * Export the recovery key emails for the escrow function (PRD V2 F08 6.5 C3 and C7; stream S05).
 *
 *   npm run export:escrow -w @scribe/emails
 *
 * Writes supabase/functions/escrow/email/templates.ts: subject, HTML and plain text for each
 * backup email, with `{placeholders}` left literal for the function to fill, plus the sender and
 * the stop page address from packages/brand. The escrow function imports nothing from outside
 * its folder (it runs in the separate escrow project), so it gets these as a generated file; a
 * test in test/escrow-export.test.ts fails when the committed file drifts from this output.
 *
 * Like the Supabase Auth templates, these use the text wordmark: the function sends no images
 * and nothing in an email loads from a server (docs/emails/README.md "Images and fonts").
 */
import { writeFileSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createElement } from 'react';
import { brand } from '@scribe/brand';
import { backupEmails } from '@scribe/content/src/emails/backup.en';
import { renderEmail, renderEmailText } from '../src/components/render';
import { templatesById } from '../src/templates';

const here = dirname(fileURLToPath(import.meta.url));
export const escrowTemplatesFile = join(resolve(here, '../../..'), 'supabase/functions/escrow/email/templates.ts');

/** Placeholders the escrow function fills (supabase/functions/escrow/restore.ts and rotate.ts). */
export const ESCROW_PLACEHOLDERS = ['when', 'device', 'holdUntil', 'stopUrl', 'requestId', 'expiresIn'] as const;

const TOKEN = /\{([a-zA-Z][a-zA-Z0-9]*)\}/g;

export async function buildEscrowTemplates(): Promise<string> {
  const emails: Record<string, { subject: string; html: string; text: string }> = {};
  for (const id of Object.keys(backupEmails)) {
    const entry = templatesById[id];
    if (!entry) throw new Error(`no template registered for ${id}`);
    const el = createElement(entry.Component, { values: {} });
    const assets = { logo: 'text' as const, webFonts: false };
    const [html, text] = await Promise.all([renderEmail(el, { assets }), renderEmailText(el, { assets })]);
    const subject = entry.copy.subject;
    const left = [...new Set([...`${subject}${html}${text}`.matchAll(TOKEN)].map((m) => m[1]!))]
      .filter((k) => !(ESCROW_PLACEHOLDERS as readonly string[]).includes(k));
    if (left.length) throw new Error(`${id}: the escrow function cannot fill ${left.join(', ')}`);
    emails[id] = { subject, html, text };
  }
  const meta = {
    from: `${brand.name} <${brand.support.email}>`,
    replyTo: brand.support.email,
    stopUrl: `https://${brand.publisher.domain}/stop`,
  };
  return [
    '// Generated by packages/emails/scripts/export-escrow.ts from packages/content/src/emails/backup.en.ts.',
    '// Do not edit by hand: run `npm run export:escrow -w @scribe/emails`. A test fails if this file drifts.',
    '',
    `export const templates = ${JSON.stringify({ meta, emails }, null, 2)} as const;`,
    '',
    'export type TemplateId = keyof typeof templates.emails;',
    '',
  ].join('\n');
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  writeFileSync(escrowTemplatesFile, await buildEscrowTemplates());
  console.log(`wrote ${escrowTemplatesFile}`);
}
